B.a59=new A.bv("\u0130lk bilet","\u015eehir Rehberi uygulamas\u0131ndan \xfccretsiz ilk u\xe7u\u015funu se\xe7.",!0)
B.a5a=new A.bv("\u0130lk g\xfcnl\xfck mesai","Kariyerinde 4 saatlik g\xfcnl\xfck g\xf6revi yap ve g\xfcnl\xfck kazanc\u0131n\u0131 al. Her oyun g\xfcn\xfcnde bir kez yapabilirsin.",!0)
B.a5b=new A.bv("Bu gece neredesin?","Konaklama uygulamas\u0131n\u0131 a\xe7. \xc7ad\u0131r \xfccretsiz ama hijyen 30 puan d\xfc\u015fer. Hostel 5 USD, otel 30 USD kar\u015f\u0131l\u0131\u011f\u0131 yerel para; ikisi de hijyeni doldurur. Temizlik kar\u015f\u0131l\u0131\u011f\u0131 \xfccretsiz hostel se\xe7ersen ertesi g\xfcn 12.00\u2019de ba\u015flars\u0131n.",!0)
B.a5c=new A.bv("Enerjini koru","Yemek uygulamas\u0131ndan toklu\u011funu y\xfckseltebilirsin. Gece yar\u0131s\u0131nda konaklama a\xe7\u0131l\u0131r.",!0)
B.a5d=new A.bv("\u0130kinci foto\u011fraf","\u015eehir Rehberi\u2019nden foto\u011fraf \xe7ek.",!0)
B.a5e=new A.bv("\u0130lk \xfclken","D\xfcnya Haritas\u0131\u2019nda bulundu\u011fun \xfclkeyi boya.",!0)
B.a5f=new A.bv("Biriktirmeye ba\u015fla","Yat\u0131r\u0131m uygulamas\u0131ndaki sembolik D\xfcnya Endeksi her sabah %1 bile\u015fik getiri sa\u011flar. \u0130stedi\u011finde paran\u0131 \xe7ekebilirsin.",!0)
B.a5g=new A.bv(2,"Yerel deneyimi tamamla",B.eH)
B.a5h=new A.bv("S\u0131radaki durak","Bulundu\u011fun \xfclkedeki gezi g\xf6revlerini tamamla ve bir gece kal. Haritada a\xe7\u0131k rotalardan yeni bir \xfclke se\xe7.",!0)
B.a5i=new A.bv(0,"Foto\u011fraf \xe7ek",B.eH)
B.a5j=new A.bv("\u015eimdi rota senin","Galeri\u2019de \xfc\xe7 foto\u011fraf\u0131n var. D\xfcnya Haritas\u0131\u2019ndan yeni bir \xfclke se\xe7ip a\xe7\u0131k biletleri inceleyebilirsin.",!1)
B.a5k=new A.bv("K\xfc\xe7\xfck hat\u0131ralar","Market uygulamas\u0131ndan yiyecek, ekipman ve \xfclkeye \xf6zg\xfc hediyelik e\u015fyalar alabilirsin. Bunlar s\u0131rt \xe7antanda birikir.",!0)
B.a5l=new A.bv("Yeni bir an\u0131","\u015eehir Rehberi\u2019nden Galeri\u2019ye \xfc\xe7\xfcnc\xfc foto\u011fraf\u0131n\u0131 ekle.",!0)
B.a5m=new A.bv("\u0130kinci \xfclken","D\xfcnya Haritas\u0131\u2019nda ikinci \xfclkeni boya.",!0)
B.a5n=new A.bv("Gelen kutun","Mail uygulamas\u0131nda f\u0131rsatlar\u0131n, davetlerin ve ba\u015far\u0131lar\u0131n birikir. Okudum d\xfc\u011fmesi \xf6d\xfclleri otomatik al\u0131r.",!0)
B.a5o=new A.bv("","",!1)
B.a5p=new A.bv("\xc7ekili\u015fi kazand\u0131n!","\u0130lk u\xe7u\u015fun, iki gece konaklama ve sigorta senin. G\xfcrcistan, S\u0131rbistan veya Bosna-Hersek aras\u0131ndan se\xe7im yapabileceksin.",!1)
B.a5q=new A.bv("\u0130lk kazan\xe7","Mini \u0130\u015fler uygulamas\u0131nda \xfcr\xfcn katalo\u011fu g\xf6revini tamamla. D\xf6rt saatte 14 USD kazanacaks\u0131n.",!0)
B.a5r=new A.bv("\xdc\xe7\xfcnc\xfc \xfclken","D\xfcnya Haritas\u0131\u2019nda \xfc\xe7\xfcnc\xfc \xfclkeni boya.",!0)
B.a5s=new A.bv(1,"Turistik yeri ziyaret et",B.eH)
B.a5t=new A.bv("Kap\u0131da bir arkada\u015f","Arkada\u015f\u0131n yol i\xe7in sana \xe7ad\u0131r ve uyku tulumu i\xe7eren bir s\u0131rt \xe7antas\u0131 haz\u0131rlam\u0131\u015f. \u015eehir Rehberi\u2019nde hediyeyi al.",!0)
B.a5u=new A.bv(3,"Bir gece konakla",B.p5)
B.a5v=new A.bv(4,"\xdclkeyi boya",B.p6)
B.a5A=new A.bv("Kendi yolunu se\xe7","Kariyer uygulamas\u0131nda d\xf6rt dijital kariyerden birini ba\u015flat. Her yeni \xfclke ilerlemeni art\u0131r\u0131r.",!0)
B.a5B=new A.bv("\u0130lk ekipman\u0131n","Mini \u0130\u015fler uygulamas\u0131ndan boncuk seti veya ukulele al. Ekipman\u0131n yeni bir i\u015f a\xe7acak.",!0)
B.a5C=new A.bv("Paran\u0131 kontrol et","C\xfczdan\u2019\u0131 a\xe7\u0131p yeni bakiyeni ve ilk kazanc\u0131n\u0131 g\xf6r.",!0)
B.a5D=new A.bv("\xdc\xe7\xfcnc\xfc \xfclkeye do\u011fru","Gezi g\xf6revlerini tamamla ve yeni bir rota se\xe7. Paran yetmiyorsa Mini \u0130\u015fler\u2019den gelir elde et.",!0)
B.a5E=new A.bv("\u0130lk kariyer i\xe7eri\u011fin","Kariyer Rotalar\u0131 uygulamas\u0131nda \xfclkeye \xf6zel 3 saatlik g\xf6revi tamamla. Bu g\xf6rev sadece se\xe7ti\u011fin kariyeri ilerletir.",!0)
B.a5F=new A.bv("\u0130lk foto\u011fraf","\u015eehir Rehberi\u2019nden gez ve foto\u011fraf \xe7ek. Kartpostal\u0131n Galeri\u2019ye eklenecek.",!0)
